input.oldString:
case "$mode" in
  global)
    dest="${XDG_CONFIG_HOME:-$HOME/.config}/kilo"
    ;;
  project)
    git -C . rev-parse --is-inside-work-tree >/dev/null 2>&1 || {
      echo "--project must run inside a git repo" >&2; exit 65; }
    dest="$(git rev-parse --show-toplevel)/.kilo"
    ;;
  prefix)
    dest="$prefix"
    ;;
esac
